    Bug 1985775 - Restart the export profile to mobile when you delete/add accounts. r=tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D264759

diff --git a/mail/components/preferences/qrExport.mjs b/mail/components/preferences/qrExport.mjs
index e173e0dbe36..eca23514848 100644
--- a/mail/components/preferences/qrExport.mjs
+++ b/mail/components/preferences/qrExport.mjs
@@ -28,8 +28,26 @@ const STEPS = ["Intro", "Codes", "Summary"];
 export const qrExportPane = {
   init() {
     this.showIntro();
+    if (this.initialized) {
+      return;
+    }
+    this.initialized = true;
+
     this.addEventListeners();
     delete document.getElementById("qrExportContent").dataset.hiddenFromSearch;
+    const reloader = {
+      observe: (subject, topic, data) => {
+        if (data == "mail.accountmanager.accounts") {
+          // Take action on a timeout, so the added account will have time
+          // to actually get added.
+          setTimeout(() => this.showIntro());
+        }
+      },
+    };
+    Services.prefs.addObserver("mail.accountmanager.accounts", reloader);
+    window.addEventListener("unload", () => {
+      Services.prefs.removeObserver("mail.accountmanager.accounts", reloader);
+    });
   },

   /**
